import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=p=>readFileSync(p,'utf8'),j=p=>JSON.parse(read(p));
const dir='content/uc3m/tema-17/';
const manual=read(dir+'manual.md'),fuentes=read(dir+'fuentes.md');
const matrix=j(dir+'matriz.json'),bank=j(dir+'preguntas.json');
const audit=read('content/uc3m/CIERRE_DOCUMENTAL_T17_20261106.md');
const cotejo=read(dir+'cotejo-integral-2026-11-04.md');
const guide=read('content/uc3m/GUIA_EXAMEN_2026.md');
const status=read('AUDITORIA_CONTINUA.md');
const packs=j('data/uc3m-repasos-complementarios-20261106.json').paquetes;
const pack=packs.find(p=>p.id==='UC3M-ADIC-20261106-T1617');
assert.equal(matrix.estado,'AUDITADO','T17 ya auditado editorialmente');
assert.equal(matrix.cobertura.length,9);
assert.equal(bank.preguntas.length,12);
assert.deepEqual([...new Set([...manual.matchAll(/^## (\d+)\. /gm)].map(m=>+m[1]).filter(n=>n<=16))],Array.from({length:16},(_,i)=>i+1));
assert.ok(manual.includes('### 13.3. Precisiones documentales 2026'));
assert.ok(manual.includes('### 13.4. Microcasos de examen'));
assert.ok(manual.includes('25/02/2010')&&manual.includes('25/02/2020'));
assert.ok(manual.includes('18/12/2025')&&manual.includes('22/01/2026'));
assert.ok(manual.includes('**B2 de español**')&&manual.includes('**B2 de inglés o equivalente**'));
assert.ok(manual.includes('art. 4.4')&&manual.includes('**50 %**'));
assert.ok(fuentes.includes('25/02/2010')&&fuentes.includes('25/02/2020'));
assert.ok(fuentes.includes('e-archivo.uc3m.es')&&fuentes.includes('11194/firmado/'));
assert.ok(fuentes.includes('CIERRE_DOCUMENTAL_T17_20261106.md'));
assert.ok(manual.includes('CIERRE_DOCUMENTAL_T17_20261106.md'));
assert.ok(audit.includes('25/02/2010')&&audit.includes('25/02/2020'));
const ids=new Set();
const arts=['2','3','3','32','22','UC3M','23','25','UC3M','44','1','6'];
for(let i=0;i<bank.preguntas.length;i++){
 const q=bank.preguntas[i];
 assert.equal(q.id,'UC3M-T17-'+String(i+1).padStart(3,'0'));
 assert.ok(!ids.has(q.id));ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(new Set(q.opciones).size,4);
 assert.ok(q.opciones.every(x=>typeof x==='string'&&x.trim()));
 assert.ok(Number.isInteger(q.correcta)&&q.correcta>=0&&q.correcta<4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampa&&q.referencia);
 assert.ok(cotejo.includes('### '+q.id+' — '+q.pregunta),'No consta cotejo por item '+q.id);
 assert.ok(q.referencia.includes('https://'),'Sin fuente externa '+q.id);
 if(arts[i]!=='UC3M')assert.ok(q.referencia.includes('art. '+arts[i]),'Referencia legal sin articulo '+q.id);
}
const t17=pack?.preguntas.filter(q=>q.tema===17);
assert.ok(t17&&t17.length===6);
const extraArts=['1','4.2','4.1','3','2','4.2'];
for(const [i,q] of t17.entries()){
 assert.equal(q.id,'UC3M-ADIC-20261106-T1617-'+String(i+7).padStart(2,'0'));
 assert.ok(!ids.has(q.id));ids.add(q.id);
 assert.equal(q.opciones.length,4);
 assert.equal(q.respuestaLiteral,q.opciones[q.correcta]);
 assert.ok(q.justificacion&&q.trampaExamen&&q.fuenteEditorial);
 assert.ok(q.referencia.includes('art. '+extraArts[i])&&q.referencia.includes('sede.uc3m.es/boel/anexo/11307/'),'BOEL sin articulo '+q.id);
}
const micro=manual.slice(manual.indexOf('### 13.4.'),manual.indexOf('## 14.'));
assert.equal((micro.match(/^\*\*Microcaso [ABCD]\./gm)||[]).length,4);
assert.equal((micro.match(/^- \*\*[ABCD]\.\*\* /gm)||[]).length,16);
assert.equal((micro.match(/^\*\*Respuesta: [ABCD]\.\*\*/gm)||[]).length,4);
assert.equal((micro.match(/^> ⚠️ \*\*¡Foco Examen!:/gm)||[]).length,4);
const c=matrix.cierreDocumentalT17_20261106;
assert.equal(c?.resultado,'CIERRE_DOCUMENTAL_REGISTRADO_CON_RESERVAS');
assert.equal(c?.coberturaPrograma,9);
assert.equal(c?.bancoOriginal,12);
assert.equal(c?.preguntasComplementarias,6);
assert.equal(c?.microcasosManual,4);
assert.equal(c?.alternativasDocumentalesTotales,88);
assert.equal(c?.certificacionIntegral,false);
assert.equal(c?.aprobacionUsuario,false);
assert.equal(c?.inspeccionVisualBOEL,false);
assert.equal(c?.pruebaNavegadorReal,false);
assert.ok(guide.includes('CIERRE_DOCUMENTAL_T17_20261106.md'));
assert.ok(status.includes('CIERRE_DOCUMENTAL_T17_20261106.md'));
assert.equal(ids.size,18);
console.log('UC3M T17 CIERRE DOCUMENTAL: 9 bloques; 12+6 interactivas; 4 microcasos; 88 alternativas; discrepancia 2010/2020 documentada; sin CI funcional ni certificacion integral');
